mod solution;

fn main() {
    let cases = [
    (r#"[100, 4, 200, 1, 3, 2]"#, r#"4"#),
    (r#"[9, 1, 2, 3, 10]"#, r#"3"#),
    (r#"
[9, 1, 2, 3, 10]
"#, r#"3"#),
    (r#"  
[100, 4, 200, 1, 3, 2]
  "#, r#"4"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS longest-consecutive-set");
}
